def check_good(n):
    memo = {}
    def is_good(num):
        if num in memo:
            return memo[num]
        s = str(num)
        digits = [int(d) for d in s]
        if len(set(digits)) != len(digits) or 0 in digits:
            memo[num] = False
            return False
        if len(s) == 1:
            memo[num] = True
            return True
        for i in range(len(s)):
            d_str = s[:i] + s[i+1:]
            if not d_str: continue
            d = int(d_str)
            if num % d == 0 and is_good(d):
                memo[num] = True
                return True
        memo[num] = False
        return False
    return is_good(n)

