import itertools

def get_all_good_numbers_up_to_n_digits(max_digits):
    memo = {}
    for i in range(1, 10):
        memo[i] = True

    good_nums = set(range(1, 10))

    for length in range(2, max_digits + 1):
        current_length_good_nums = set()
        for digits in itertools.permutations(range(1, 10), length):
            n = int("".join(map(str, digits)))
            s = str(n)
            for i in range(len(s)):
                d_str = s[:i] + s[i+1:]
                if not d_str: continue
                d = int(d_str)
                if n % d == 0 and d in good_nums:
                    current_length_good_nums.add(n)
                    break
        good_nums.update(current_length_good_nums)
    return sorted(list(good_nums))

