def get_max_good(max_digits):
    memo = {}
    for i in range(1, 10):
        memo[i] = True

    max_good = 0
    for length in range(1, max_digits + 1):
        # We'll search from largest to smallest for each length to find the max_good quickly.
        # But to be sure we need to check all.
        # For a given length, permutations can be sorted in descending order.
        for digits in itertools.permutations(range(1, 10), length):
            # Wait, to get descending, we can't just use permutations.
            # Let's just use the current method.
            pass

    # Let's use a better approach to find the max good number.
    # Good numbers of length L must have a good divisor of length L-1.
    # Let's use this!

    good_by_length = [set() for _ in range(max_digits + 1)]
    for i in range(1, 10):
        good_by_length[1].add(i)

    for length in range(2, max_digits + 1):
        # A number of 'length' is good if it has a good divisor of 'length-1'
        # This is not quite right, because the divisor could have length-1 or less.
        # But the definition says "removing ONE of its digits".
        # Removing one digit from a number of length L always results in a number of length L-1.
        # So the divisor MUST have length L-1.

        # Let's find all good numbers of length L.
        # They must be formed by taking a good number of length L-1 and inserting a digit.
        for d in good_by_length[length-1]:
            d_str = str(d)
            for digit in range(1, 10):
                # Insert 'digit' into 'd_str' at all possible positions
                for pos in range(len(d_str) + 1):
                    new_str = d_str[:pos] + str(digit) + d_str[pos:]
                    if len(set(new_str)) == len(new_str) and '0' not in new_str:
                        n = int(new_str)
                        if n % d == 0:
                            good_by_length[length].add(n)

        if not good_by_length[length]:
            break

    max_val = 0
    for length in range(1, max_digits + 1):
        if good_by_length[length]:
            max_val = max(max_val, max(good_by_length[length]))
    return max_val

